def _trunc_summary(self, trace_text):
    text = str(trace_text)
    # Keep only error-related evidence to improve conciseness
    lines = text.splitlines()
    out = []
    budget = 900  # characters budget
    for i, ln in enumerate(lines):
        if "ERROR" in ln or "AssertionError" in ln:
            # include this line plus the next 2 lines of context
            for j in range(i, min(i + 3, len(lines))):
                if sum(len(x) + 1 for x in out) > budget:
                    break
                out.append(lines[j])
    # Fallback: if no error lines, just keep the tail
    if not out:
        return text[-500:]
    # De-duplicate while preserving order
    seen = set()
    dedup = []
    for ln in out:
        if ln not in seen:
            seen.add(ln)
            dedup.append(ln)
    return "\n".join(dedup)[-500:]

